pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _newOwner) public {
        // 1. The owner is initially the deployer of C in setUp (this test contract),
        //    so we can prank as the owner to call transferOwnership.
        vm.prank(address(this));
        c.transferOwnership(_newOwner);
        // 2. After the call, the correct contract sets owner to _newOwner,
        //    while the buggy one sets it to address(0).
        //    The general rule: after transferOwnership(_newOwner), the owner must equal _newOwner.
        //    The bug breaks this whenever _newOwner != address(0).
        assertTrue(c.owner() == _newOwner);
    }
}

