        c.transferOwnership(caller);
        // Caller (now owner) invokes transferOwnership
        vm.prank(caller);
        c.transferOwnership(newOwner);
        // After a successful transferOwnership, the owner must equal the caller (current owner)
        assertTrue(c.owner() == caller);
    }
}

