pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, address newOwner, address caller) public {
        vm.assume(actor != address(0));
        vm.assume(newOwner != address(0));
        vm.assume(caller != address(0));
        vm.assume(actor != caller);
        vm.assume(newOwner != caller);

        // Set initial owner as actor
        vm.prank(msg.sender);
        c.transferOwnership(actor);

        // caller calls transferOwnership with newOwner
        vm.prank(caller);
        try c.transferOwnership(newOwner) {
            // If it succeeded, a non-owner changed the owner — the rule checks that the new owner is not caller
        } catch {
            // If it reverted, the state didn't change, so the property holds vacuously
        }

        // Property: If a transferOwnership call from a non-owner succeeds (no revert), the owner should become newOwner, never msg.sender.
        // More generally: After any sequence, owner is never set to an address that wasn't passed as _newOwner in a successful transferOwnership call.
        // But the simplest invariant that breaks: the owner is never caller when caller != actor and caller != newOwner.
        assertTrue(c.owner() != caller);
    }
}

