pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner, bool succeed) public {
        // restrict newOwner to be different from the current owner to avoid a no-op case
        vm.assume(newOwner != c.owner());
        // prank as current owner; the call should succeed
        vm.prank(c.owner());
        bool ok;
        try c.transferOwnership(newOwner) { ok = true; } catch { ok = false; }
        // if succeed is true, we force the call to succeed by assuming the prank didn't revert
        vm.assume(succeed);
        vm.assume(ok);
        // After a successful transferOwnership call by the current owner,
        // the owner must equal the newOwner address.
        assertTrue(c.owner() == newOwner);
    }
}

