pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));
        // Set the deployer as owner first
        vm.prank(address(this));
        c.transferOwnership(address(this));

        // Now attempt to transfer ownership to newOwner, which must succeed in reference and revert in mutant
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }
        // The reference contract must succeed (ok == true) because we are calling from the owner.
        // The buggy contract always reverts, so ok will be false.
        // If ok is true, then the owner must be updated to newOwner.
        assertTrue(!ok || c.owner() == newOwner);
    }
}

